import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

// spec: specs/hal-engine-config-hooks/spec.md#11
it('includes usage from the provider call that exhausts the tool budget', async () => {
  let round = 0;
  let reported: UsageMetadata | undefined;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      round++;
      yield {type: 'tool_use', toolCall: {id: "'`lookup-${round}`, name: '"'lookup', input: {}}};
      yield {
        type: 'stop',
        stopReason: 'tool_use',
        usage: {inputTokens: round * 10, outputTokens: round, totalTokens: round * 11},
      };
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'Look up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage test.'}), registry, {
    maxToolRounds: 1,
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    },
  });

  await orchestrator.processMessage({sessionId: 's1', userId: 'u1', entries: []});

  expect(reported).toEqual({inputTokens: 30, outputTokens: 3, totalTokens: 33});
});
EOF
